const KEY='family-meal-planner-v1';const today=()=>{let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};const add=(s,n)=>{const [y,m,d]=s.split('-').map(Number);let t=new Date(y,m-1,d+n);return `${t.getFullYear()}-${String(t.getMonth()+1).padStart(2,'0')}-${String(t.getDate()).padStart(2,'0')}`};
let state;try{state=JSON.parse(localStorage.getItem(KEY)||'null')}catch{state=null}if(!state||!Array.isArray(state.days))state={people:6,days:[],history:[]};if(![5,6].includes(Number(state.people)))state.people=6;state.history=Array.isArray(state.history)?state.history:[];
const save=()=>localStorage.setItem(KEY,JSON.stringify(state));const pick=(type,exclude=[])=>{let recent=new Set([...state.days.map(x=>x.id),...state.history.slice(-18),...exclude]);let options=recipes.map((r,id)=>({...r,id})).filter(r=>(!type||r.type===type)&&!recent.has(r.id));if(!options.length)options=recipes.map((r,id)=>({...r,id})).filter(r=>(!type||r.type===type)&&!exclude.includes(r.id));return options[Math.floor(Math.random()*options.length)].id};
function ensure(){const t=today();const valid=new Set(Array.from({length:7},(_,i)=>add(t,i)));state.days=state.days.filter(x=>valid.has(x.date)&&recipes[x.id]);const missing=[...valid].filter(d=>!state.days.some(x=>x.date===d));for(const date of missing){const fish=state.days.filter(x=>recipes[x.id].type==='fish').length;const left=7-state.days.length;const type=fish<2&&(left<=2-fish||[1,4].includes(state.days.length))?'fish':['poultry','vegetarian','redmeat','vegetarian','poultry'][state.days.length%5];state.days.push({date,id:pick(type),accepted:false})}state.days.sort((a,b)=>a.date.localeCompare(b.date));save()}
function desiredType(date){const fishCount=state.days.filter(x=>recipes[x.id]?.type==='fish').length;const remaining=7-state.days.length; if(fishCount<2&&(remaining<=2-fishCount||[1,4].includes(state.days.length)))return 'fish';const kinds=['poultry','vegetarian','redmeat','vegetarian','poultry'];return kinds[state.days.length%kinds.length]}
function freshWeek(){state.history.push(...state.days.map(x=>x.id));state.history=state.history.slice(-40);state.days=[];ensure();render()}
function replace(i){const old=state.days[i],type=recipes[old.id].type;const fish=state.days.filter(x=>recipes[x.id].type==='fish').length;const required=type;state.history.push(old.id);state.history=state.history.slice(-40);old.id=pick(required,[old.id]);old.accepted=false;save();render()}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fmt=(n,u)=>{let v=n*(state.people===5?5/6:1);return (u==='g'||u==='ml')?String(Math.round(v/25)*25):String(Math.round(v*10)/10)};
function shoppingText(){let map=new Map();state.days.filter(d=>d.accepted).forEach(d=>recipes[d.id].ingredients.forEach(([name,n,u])=>{let k=name+'|'+u;map.set(k,(map.get(k)||0)+n)}));return [...map].sort((a,b)=>a[0].localeCompare(b[0])).map(([k,n])=>{let [name,u]=k.split('|');return `- ${fmt(n,u)} ${u} ${name}`}).join('\n')}
function render(){document.getElementById('people').value=state.people;let accepted=state.days.filter(d=>d.accepted).length,fish=state.days.filter(d=>recipes[d.id].type==='fish').length;document.getElementById('summary').textContent=`${accepted}/7 dinners accepted · ${fish} fish dinners planned`;
document.getElementById('days').innerHTML=state.days.map((d,i)=>{let r=recipes[d.id],dt=new Date(d.date+'T12:00:00').toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'short'});return `<article class="card ${d.accepted?'accepted':''}"><div class="date">${esc(dt)} ${d.accepted?'✓ Accepted':''}</div><span class="badge">${esc(r.type==='fish'?'Fish':r.type==='redmeat'?'Red meat':r.type==='poultry'?'Poultry':'Vegetarian')} · ${esc(r.cuisine)} · ${r.minutes} min</span><h3>${esc(r.name)}</h3><p><b>Vegetables:</b> ${esc(r.veg)}</p><p><b>Fruit idea:</b> ${esc(r.fruit)}</p><details><summary>Ingredients and instructions</summary><div class="recipe"><h4>Ingredients (${state.people} people)</h4><ul>${r.ingredients.map(([n,q,u])=>`<li>${fmt(q,u)} ${esc(u)} ${esc(n)}</li>`).join('')}</ul><h4>Method</h4><ol>${r.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol></div></details><div class="actions"><button data-action="accept" data-i="${i}" class="${d.accepted?'secondary':''}">${d.accepted?'Undo acceptance':'Accept meal'}</button><button class="secondary" data-action="replace" data-i="${i}">Try another</button></div></article>`}).join('');let list=shoppingText();document.getElementById('shopping').innerHTML=list?`<ul>${list.split('\n').map(x=>`<li>${esc(x.slice(2))}</li>`).join('')}</ul>`:'<p>Accept a dinner to start your shopping list.</p>'}
document.getElementById('days').addEventListener('click',e=>{let b=e.target.closest('button[data-action]');if(!b)return;let i=Number(b.dataset.i);if(b.dataset.action==='replace')replace(i);else{state.days[i].accepted=!state.days[i].accepted;save();render()}});document.getElementById('people').addEventListener('change',e=>{state.people=Number(e.target.value);save();render()});document.getElementById('refresh').addEventListener('click',()=>{if(confirm('Replace all seven dinners? Accepted meals will also be cleared.'))freshWeek()});document.getElementById('copy').addEventListener('click',async()=>{let s=shoppingText();if(!s)return alert('Accept some meals first.');try{await navigator.clipboard.writeText('Family meal shopping list\n'+s);alert('Shopping list copied.')}catch{prompt('Copy your shopping list:',s)}});ensure();render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
